#!/usr/bin/env node
// Generates the launcher icon list from the launcher's own source, so the list is never typed by hand.
//   node kit/schema/gen-icons.mjs <path to utilityIconMap.ts>            rewrite the three generated files
//   node kit/schema/gen-icons.mjs <path to utilityIconMap.ts> --check    exit 1 if they differ from the source
// Source of truth: bolt-pwa src/lib/components/ui/utilityIconMap.ts, the UTILITY_ICON_MAP object.
// Generated: kit/schema/icons.json, the icon enum in kit/schema/row.schema.json, kit/python/bolt_app_kit/icons_data.py.
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { fileURLToPath } from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));
export const OUT = {
	json: path.join(here, 'icons.json'),
	schema: path.join(here, 'row.schema.json'),
	py: path.join(here, '..', 'python', 'bolt_app_kit', 'icons_data.py'),
};

export function parseIconKeys(ts) {
	const start = ts.indexOf('export const UTILITY_ICON_MAP');
	if (start < 0) throw new Error('UTILITY_ICON_MAP not found');
	const open = ts.indexOf('{', start), close = ts.indexOf('\n};', open);
	if (open < 0 || close < 0) throw new Error('UTILITY_ICON_MAP body not found');
	const keys = [];
	for (const raw of ts.slice(open + 1, close).split('\n')) {
		const line = raw.replace(/\/\/.*$/, '').trim();
		const m = /^(?:'([^']+)'|([A-Za-z_][A-Za-z0-9_]*))\s*(?::|,|$)/.exec(line);
		if (m) keys.push(m[1] ?? m[2]);
	}
	return [...new Set(keys)].sort();
}

export function render(keys, sha) {
	const json = JSON.stringify({ source: 'bolt-pwa src/lib/components/ui/utilityIconMap.ts (UTILITY_ICON_MAP)', source_sha256: sha, icons: keys }, null, 2) + '\n';
	const py = `# Generated by kit/schema/gen-icons.mjs from the launcher's UTILITY_ICON_MAP. Do not edit.\n# source_sha256: ${sha}\nICONS = frozenset((\n${keys.map((k) => `    ${JSON.stringify(k)},`).join('\n')}\n))\n`;
	const schema = JSON.parse(fs.readFileSync(OUT.schema, 'utf8'));
	schema.$defs.icon.enum = keys;
	schema.$defs.icon['x-source-sha256'] = sha;
	return { json, py, schema: JSON.stringify(schema, null, 2) + '\n' };
}

if (process.argv[1] && fs.realpathSync(process.argv[1]) === fs.realpathSync(fileURLToPath(import.meta.url))) {
	const [src, flag] = process.argv.slice(2);
	if (!src) { console.error('usage: gen-icons.mjs <utilityIconMap.ts> [--check]'); process.exit(2); }
	const ts = fs.readFileSync(src, 'utf8');
	const out = render(parseIconKeys(ts), crypto.createHash('sha256').update(ts).digest('hex'));
	let drift = false;
	for (const k of ['json', 'schema', 'py']) {
		const cur = fs.existsSync(OUT[k]) ? fs.readFileSync(OUT[k], 'utf8') : '';
		if (cur !== out[k]) { drift = true; if (flag !== '--check') fs.writeFileSync(OUT[k], out[k]); }
	}
	if (flag === '--check') { console.log(drift ? 'DRIFT: regenerate with gen-icons.mjs' : 'icons match the launcher source'); process.exit(drift ? 1 : 0); }
	console.log(drift ? 'regenerated' : 'already current');
}
